import { execFile } from "node:child_process";
import { promisify } from "node:util";
const exec = promisify(execFile);
export async function createGitCleanupBranch(projectRoot, options) {
    const branch = options.branchName || "treeprune/cleanup-dead-code";
    // 1. Verify project is inside a git repository
    try {
        const { stdout } = await exec("git", ["rev-parse", "--is-inside-work-tree"], {
            cwd: projectRoot,
        });
        if (stdout.trim() !== "true") {
            return { success: false, branch, isGitRepo: false, error: "Not a git repository" };
        }
    }
    catch (err) {
        return { success: false, branch, isGitRepo: false, error: "Git is not installed or repo not found" };
    }
    try {
        // 2. Create and checkout dedicated cleanup branch
        try {
            await exec("git", ["checkout", "-b", branch], { cwd: projectRoot });
        }
        catch {
            // If branch already exists, switch to it
            await exec("git", ["checkout", branch], { cwd: projectRoot });
        }
        // 3. Stage changes
        const filesToStage = [...options.modifiedFiles, ...options.deletedFiles];
        if (filesToStage.length > 0) {
            await exec("git", ["add", "-A"], { cwd: projectRoot });
        }
        // 4. Create commit
        const savedKb = Math.round(options.deadBytes / 1024);
        const defaultMsg = `chore(prune): eliminate dead code and recover ${savedKb} KB\n\n- Deleted files: ${options.deletedFiles.length}\n- Modified files: ${options.modifiedFiles.length}\n\nAutomated cleanup generated by TreePrune`;
        const message = options.commitMessage || defaultMsg;
        await exec("git", ["commit", "-m", message], { cwd: projectRoot });
        // 5. Get commit hash
        const { stdout: hashOut } = await exec("git", ["rev-parse", "HEAD"], {
            cwd: projectRoot,
        });
        return {
            success: true,
            branch,
            commitHash: hashOut.trim(),
            isGitRepo: true,
        };
    }
    catch (err) {
        return {
            success: false,
            branch,
            isGitRepo: true,
            error: err.message,
        };
    }
}
